theorem toGroup_mk {α K : Type*} [Group K] {rels : Set (FreeGroup α)} {f : α → K}
    (h : ∀ r ∈ rels, FreeGroup.lift f r = 1) (r : FreeGroup α) :
    PresentedGroup.toGroup h (PresentedGroup.mk rels r) = FreeGroup.lift f r

theorem primrec_list_all {α β : Type*} [Primcodable α] [Primcodable β] {f : α → List β}
    {p : α → β → Bool} (hf : Primrec f) (hp : Primrec₂ p) :
    Primrec fun a => (f a).all (p a)
